command:
$env:PYTHONUTF8 = '1'
Get-CimInstance Win32_Process -Filter "Name = 'python.exe'" | Where-Object { $_.CommandLine -like '*--basetemp=.pytest_cache/session-isolation-prepush' } | ForEach-Object { Stop-Process -Id $_.ProcessId }
python -B -m pytest -o addopts= -q --basetemp=.pytest_cache/session-isolation-prepush-native
